uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

out vec4 fragColor;

// --- Helper Functions ---

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// 2D Hash for Voronoi Web
vec2 hash22(vec2 p) {
    p = vec2(dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)));
    return fract(sin(p)*43758.5453) * 2.0 - 1.0;
}

// 1D Hash for Activation Seeds
float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// Bio-electric Palette (Teals, Blues, Purples)
vec3 palette(float t) {
    vec3 a = vec3(0.3, 0.4, 0.5);
    vec3 b = vec3(0.7, 0.6, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.00, 0.15, 0.30);
    return a + b * cos(6.28318 * (c * t + d));
}

// Neural Web (Voronoi Edges and Nodes)
// Returns vec3: x = edge distance, y = node distance, z = cell activation hash
vec3 getNeuralWeb(vec2 uv, float t) {
    vec2 n = floor(uv);
    vec2 f = fract(uv);

    vec2 mg, mr;
    float md = 8.0;

    // Pass 1: Find nearest node (soma/cell body)
    for(int j=-1; j<=1; j++) {
        for(int i=-1; i<=1; i++) {
            vec2 g = vec2(float(i),float(j));
            vec2 o = hash22(n + g) * 0.5 + 0.5; // 0 to 1
            o = 0.5 + 0.4 * sin(t * 1.5 + 6.2831 * o); // Biological pulsing
            vec2 r = g + o - f;
            float d = dot(r,r);
            if(d<md) {
                md = d;
                mr = r;
                mg = g;
            }
        }
    }

    md = 8.0;
    // Pass 2: Distance to web edges (dendrites/axons)
    for(int j=-2; j<=2; j++) {
        for(int i=-2; i<=2; i++) {
            vec2 g = mg + vec2(float(i),float(j));
            vec2 o = hash22(n + g) * 0.5 + 0.5;
            o = 0.5 + 0.4 * sin(t * 1.5 + 6.2831 * o);
            vec2 r = g + o - f;
            if(dot(mr-r,mr-r)>0.00001) {
                md = min(md, dot( 0.5*(mr+r), normalize(r-mr) ));
            }
        }
    }

    // Pass a random activation value based on the closest cell
    float activation = hash(n + mg);

    return vec3(md, length(mr), activation);
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing
    float spd = (u_speed <= 0.0) ? 0.2 : u_speed;
    float t = iTime * spd;

    // --- Background (Dark Organic Tissue) ---
    vec3 bgTop = vec3(0.02, 0.05, 0.12); // Deep Fluid Blue
    vec3 bgBottom = vec3(0.08, 0.01, 0.05); // Deep Tissue Purple

    // Cellular background fluid movement
    bgTop += 0.02 * sin(t * 0.5);
    vec3 finalColor = mix(bgBottom, bgTop, uv0.y + 0.5 + 0.2 * sin(uv0.x * 2.0 + t * 0.4));

    // 3. Layer Loop
    float density = (u_layers <= 0.0) ? 3.0 : u_layers;
    float scale = (u_scale <= 0.0) ? 3.0 : u_scale * 4.0; // Scaled up for cellular look
    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;

    for(float i = 0.0; i < 5.0; i++) {
        if(i >= density) break;

        // --- Space Distortion for Neuro Layer ---
        vec2 layerUV = uv0 * scale * (1.0 + i * 0.6);

        // Organic drifting
        layerUV.y -= t * 0.2 * (i + 1.0); 
        layerUV *= rot(sin(t * 0.1 + i) * 0.2);

        // --- Neural Geometry ---
        vec3 neuro = getNeuralWeb(layerUV + vec2(i * 14.3, i * 27.5), t);
        float edgeDist = neuro.x;
        float nodeDist = neuro.y;
        float activation = neuro.z; // 0.0 to 1.0

        // --- Dendrite & Synapse Glow ---
        // Threads (edges)
        float threadThickness = 12.0 + i * 2.0;
        float threads = exp(-edgeDist * threadThickness);

        // Synapses (nodes)
        float synapses = exp(-nodeDist * 25.0) * 1.5;

        // Action Potentials (Signals moving through the web)
        // Flashes bright when the sine wave hits the activation threshold
        float signal = smoothstep(0.8, 1.0, sin(activation * 20.0 - t * 10.0));

        // Combine structural glow + bio-electric signals
        float structureGlow = threads * 0.6 + synapses * 0.8;
        float electricGlow = (threads + synapses * 2.0) * signal * 2.0;

        // 4. Coloring
        vec3 col = palette(length(uv0) * 0.2 + i * 0.15 + t * u_color_cycle + activation * 0.1);

        // High energy signal color (Electric Cyan/White)
        vec3 sparkCol = mix(col, vec3(0.8, 1.0, 1.0), 0.8);

        // Accumulate: Tissue + Signals
        finalColor += col * structureGlow * brightness * 0.5;
        finalColor += sparkCol * electricGlow * brightness * 0.8;
    }

    // 5. Post-Processing
    float vig = 1.0 - length(uv0) * 0.5;
    finalColor *= vig;

    // Smooth Clamp / Tone Mapping (filmic organic feel)
    finalColor = smoothstep(-0.02, 1.2, finalColor);

    fragColor = vec4(finalColor, 1.0);
}
